parameters.jsCode:
const citas = [
  {
    sede: 'Hospital Internacional de Colombia (HIC)',
    estado: 'APPROVED',
    especialidad: 'Medicina General'
  }
];

const porSede = {};
const porEspecialidad = {};

for (const cita of citas) {
  if (!porSede[cita.sede]) {
    porSede[cita.sede] = { total: 0, APPROVED: 0, COMPLETED: 0, NO_SHOW: 0, CANCELLED: 0 };
  }
  porSede[cita.sede].total++;
  if (porSede[cita.sede][cita.estado] !== undefined) porSede[cita.sede][cita.estado]++;
  porEspecialidad[cita.especialidad] = (porEspecialidad[cita.especialidad] ?? 0) + 1;
}

const resumenSedes = Object.entries(porSede)
  .map(([sede, datos]) => `- ${sede}: ${datos.total} total | Aprobadas: ${datos.APPROVED} | Completadas: ${datos.COMPLETED} | No asistió: ${datos.NO_SHOW} | Canceladas: ${datos.CANCELLED}`)
  .join('\n');
const resumenEspecialidades = Object.entries(porEspecialidad)
  .map(([especialidad, total]) => `- ${especialidad}: ${total}`)
  .join('\n');

return [{ json: {
  fecha: '2026-09-30',
  totalCitas: citas.length,
  resumenSedes,
  resumenEspecialidades,
  incidenciasApi: 'Sin incidencias de API.'
} }];

